<section><form class="card" method="POST" action="{{ route('petugas.pengaduan.forward',$pengaduan) }}">@csrf<h3 style="margin:0 0 16px">Prioritas &amp; penerusan</h3><div class="field"><label>Tingkat prioritas *</label><div class="choice">@foreach(['tinggi'=>'Tinggi','sedang'=>'Sedang','rendah'=>'Rendah'] as $value=>$label)<label><input type="radio" name="prioritas" value="{{ $value }}" @checked(old('prioritas',$pengaduan->prioritas)===$value)>{{ $label }}</label>@endforeach</div></div><div class="field"><label>Batas waktu penanganan *</label><input type="date" name="batas_waktu" min="{{ now()->toDateString() }}" value="{{ old('batas_waktu',optional($pengaduan->batas_waktu)->format('Y-m-d')) }}" required></div><div class="field"><label>Diteruskan ke *</label><div class="choice"><label><input type="radio" name="jenis_tujuan" value="rt_rw" @checked(old('jenis_tujuan','rt_rw')==='rt_rw') onchange="switchTarget()">RT/RW</label><label><input type="radio" name="jenis_tujuan" value="seksi" @checked(old('jenis_tujuan')==='seksi') onchange="switchTarget()">Seksi</label></div></div><div class="field" id="rt-field"><label>RT / RW</label><select name="id_rt_rw"><option value="">Pilih RT/RW</option>@foreach($rtRws as $rt)<option value="{{ $rt->id_rt_rw }}" @selected(old('id_rt_rw')==$rt->id_rt_rw)>RT {{ $rt->no_rt }} / RW {{ $rt->no_rw }} — {{ $rt->nama_ketua }}</option>@endforeach</select></div><div class="field" id="seksi-field"><label>Seksi terkait</label><select name="id_seksi"><option value="">Pilih seksi</option>@foreach($seksis as $seksi)<option value="{{ $seksi->id_seksi }}" @selected(old('id_seksi')==$seksi->id_seksi)>{{ $seksi->nama_seksi }} — {{ $seksi->penanggung_jawab }}</option>@endforeach</select></div><div class="field"><label>Catatan penerusan *</label><textarea name="catatan" required minlength="5" placeholder="Tuliskan instruksi atau keterangan untuk pihak penerima...">{{ old('catatan') }}</textarea></div><div class="actions"><a class="btn cancel" href="{{ route('petugas.pengaduan.index') }}">Batal</a><button class="btn" type="submit">Teruskan</button></div></form></section></div></main>
<script>function switchTarget(){const v=document.querySelector('input[name="jenis_tujuan"]:checked')?.value;document.getElementById('rt-field').style.display=v==='rt_rw'?'block':'none';document.getElementById('seksi-field').style.display=v==='seksi'?'block':'none';}switchTarget();</script></body></html>
